INSERT INTO `produk_tokopedia` (`id`, `kategori`, `nama_produk`, `harga_utama`, `harga_asli`, `diskon`, `terjual`, `rating`, `spesifikasi`, `deskripsi`, `link`, `gambar`, `waktu_scrape`) VALUES
(140, 'baju', 'Fadkhera Baju Koko Pria Lengan Panjang & Pendek Terbaru 2026 Premium Kemeja Muslim Casual Thariq Black', 'Rp229.120', 'Rp359.000', '-', 'Terjual 17', '5', 'Kondisi: Baru | Berat Satuan: 300 g | Min. Beli: 1 Buah | Kategori: Baju Koko Pria | Etalase: Semua Etalase', 'Tampil maksimal disetiap kesempatan dengan Baju Koko Pria Lengan Panjang & Pendek Terbaru 2026 Premium Kemeja Muslim Casual dari Fadkhera. Kemeja koko premium terbaru ini dirancang khusus untuk memberikan kenyamanan ekstra, baik untuk momen ibadah maupun aktivitas produktif Anda.\n\n\nSebagai opsi daily wear yang modern, baju muslim pria ini memiliki potongan kasual yang sangat fleksibel. Sempurna saat dipadukan dengan koleksi celana panjang harian kami, atau dilapisi dengan jaket saat Anda membutuhkan gaya berlapis (layering) yang rapi namun tetap santai.\n\n\nPENAWARAN SPESIAL: Dapatkan bonus eksklusif Sarung gratis untuk pembelian 500rb (selama persediaan masih ada).\n\n\nCharacter :\n- Premium quality dengan detail tinggi\n- Handfeel berbahan mengkilat soft touch\n- Material bertekstur lembut dan tebal\n- Variasi Design yang unik\n\n\nFeature :\n- Modern spread collar\n- Bagian lengan yang bisa disesuaikan (Long Sleeve)\n- Mudah di setrika dan tidak gampang kusut\n- Modern size cutting (antara reguler dan slimfit)\n\n\nColor :\nBlack\n\n\nMaterial :\nEasy Care Soft Touch Fabrics\n\n\nWarna foto mungkin tidak 100% sama dengan produk aslinya, disebabkan oleh faktor cahaya pada saat take foto, atau kondisi gadget yang digunakan\n\n\n1. Harap dipastikan bahwa pesanan sudah sesuai sebelum check out\n2. Klaim produk wajib menyertakan video unboxing\n3. Setelah barang sampai mohon untuk di cek kelengkapan dan pastikan barang yang diterima dalam kondisi baik sebelum tekan \"Pesan Diterima\"\n4. Jangan lupa untuk memberikan review untuk produk yang sudah diterima\n\n\nJazakallah khoiron\n#BajuKokoPria #KemejaKoko #BajuMuslimPria #KokoLenganPendek #KokoLenganPanjang #Fadkhera #OutfitPria #KokoPremium2026\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/fadkhera-thariq-baju-koko-pria-modern-premium-hitam-atasan-muslim-lengan-panjang-1733868990667392897-1736087820986582913?extParam=ivf%3Dfalse%26keyword%3Dbaju%26search_id%3D202609280723488DD48D6A2E2CAD040FJI%26src%3Dsearch', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:24:40'),
(141, 'baju', 'Fadkhera X Muslim Show - MS - Embrace - Baju Pria Dewasa Oversized', 'Rp219.000', '-', '-', 'Terjual 4', '5', 'Kondisi: Baru | Berat Satuan: 260 g | Min. Beli: 1 Buah | Kategori: Kaos Pria | Etalase: Semua Etalase', 'Fadkhera X Muslim Show -\nSeries Oversized T-Shirt eksklusif dengan artwork penuh filosofi yang menampilkan perjalanan iman seorang muslim: harap akan ampunan Allah, dan takut akan siksa-Nya. Dua unsur ini menjadi fondasi keseimbangan hidup seorang muslim, dan dituangkan ke dalam desain yang artistik, minimal, namun sarat makna.\n\nWarna navy yang deep memberi kesan calm, classy, dan timeless. Penampilan ini bikin lebih percaya diri dengan gaya simple namun penuh pesan spiritual.\n\nMS - Embrace T-Shirt Oversized Navy\n\nCharacter\n\n\nPremium cotton dengan kualitas breathable\nSoft touch dengan handfeel halus dan nyaman\nMaterial tebal, solid, dan awet\nArtwork eksklusif hasil kolaborasi Fadkhera x Muslimshow\n\nFeature\n\n\nOversized fit dengan cutting modern\nPrint plastisol doff finish (soft handfeel)\nMudah dipadukan untuk berbagai gaya streetwear\nWarna solid yang tidak mudah pudar\n- Baju Pria Dewasa Oversized\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/fadkhera-x-muslim-show-ms-embrace-baju-pria-dewasa-oversized-1732618263383934849?extParam=ivf%3Dfalse%26keyword%3Dbaju%26search_id%3D202609280723488DD48D6A2E2CAD040FJI%26src%3Dsearch', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:24:50'),
(142, 'baju', 'Fadkhera Navy Series Baju Koko Pria Lengan Panjang & Pendek Terbaru 2026 Premium Kemeja Muslim Casual Dzimar Aqta Fattah', 'Rp218.272', 'Rp359.000', '-', '0 Terjual', 'Belum ada ', '', 'Tampil maksimal disetiap kesempatan dengan Baju Koko Pria Lengan Panjang & Pendek Terbaru 2026 Premium Kemeja Muslim Casual dari Fadkhera. Kemeja koko premium terbaru ini dirancang khusus untuk memberikan kenyamanan ekstra, baik untuk momen ibadah maupun aktivitas produktif Anda.\n\n\nSebagai opsi daily wear yang modern, baju muslim pria ini memiliki potongan kasual yang sangat fleksibel. Sempurna saat dipadukan dengan koleksi celana panjang harian kami, atau dilapisi dengan jaket saat Anda membutuhkan gaya berlapis (layering) yang rapi namun tetap santai.\n\n\nCharacter :\n- Premium quality dengan detail tinggi\n- Handfeel berbahan mengkilat soft touch\n- Material bertekstur lembut dan tebal\n- Variasi Design yang unik\n\n\nFeature :\n- Modern spread collar\n- Bagian lengan yang bisa disesuaikan (Long Sleeve)\n- Mudah di setrika dan tidak gampang kusut\n- Modern size cutting (antara reguler dan slimfit)\n\n\nColor : Navy\n\n\nMaterial : Soft Touch Fabric\n\n\nWarna foto mungkin tidak 100% sama dengan produk aslinya, disebabkan oleh faktor cahaya pada saat take foto, atau kondisi gadget yang digunakan\n\n\n1. Harap dipastikan bahwa pesanan sudah sesuai sebelum check out\n2. Klaim produk wajib menyertakan video unboxing\n3. Setelah barang sampai mohon untuk di cek kelengkapan dan pastikan barang yang diterima dalam kondisi baik sebelum tekan \"Pesan Diterima\"\n4. Jangan lupa untuk memberikan review untuk produk yang sudah diterima\n\n\nJazakallah khoiron\n#BajuKokoPria #KemejaKoko #BajuMuslimPria #KokoLenganPendek #KokoLenganPanjang #Fadkhera #OutfitPria #KokoPremium2026\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/best-seller-fadkhera-dzimar-baju-koko-pria-modern-premium-atasan-muslim-lengan-panjang-1729633871340472193-1736084830865295233', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:34:37'),
(143, 'baju', 'Fadkhera Kamil Navy Baju Koko Basic Pria Dewasa Kemeja Polos Lengan Panjang', 'Rp222.400', 'Rp279.000', '-', 'Terjual 10', '5', 'Kondisi: Baru | Berat Satuan: 350 g | Min. Beli: 1 Buah | Kategori: Kemeja Pria | Etalase: Sale Up To 35', 'Essential shirt series berwarna navy yang simpel dan timeless. Warna navy dalam fashion melambangkan luxury, earthy dan maturity.\n\nOVERVIEW\n\n– Essential shirt berkualitas premium dengan detail tinggi\n– Size modern fit diantara Reguler dan Slim Fit.\n– Modern spread collar.\n– Handfeel bahan lembut dan mengkilap soft eksklusif.\n– Tidak mudah kusut.\n– Mudah disetrika.\n– Serat benang padat.\n\nPETUNJUK PERAWATAN\n\nMencuci dengan suhu yang rendah, tidak diberi pemutih, dan disetrika dengan suhu sedang akan membantu mempertahankan warna dan bahan.\n\n- Cuci dengan suhu 30°C\n- Jangan diberi pemutih\n- Dicuci kering profesional\n- Dikeringkan mesin pengering dengan suhu rendah\n- Disetrika dengan suhu sedang\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/fadkhera-kamil-navy-baju-koko-basic-pria-dewasa-kemeja-polos-lengan-panjang-1731686499204630401', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:34:48'),
(144, 'baju', 'Fadkhera Nauzan Baju Koko Pria Muslim Modern Kemko Lengan Panjang', 'Rp249.000', 'Rp359.000', '-', 'Terjual 7', '5', 'Kondisi: Baru | Berat Satuan: 300 g | Min. Beli: 1 Buah | Kategori: Baju Koko Pria | Etalase: Semua Etalase', 'Warna foto mungkin tidak 100% sama dengan produk aslinya, disebabkan oleh faktor cahaya pada saat take foto, atau kondisi gadget yang digunakan\n\n\n1. Harap dipastikan bahwa pesanan sudah sesuai sebelum check out\n2. Klaim produk wajib menyertakan video unboxing\n3. Setelah barang sampai mohon untuk di cek kelengkapan dan pastikan barang yang diterima dalam kondisi baik sebelum tekan \"Pesan Diterima\"\n4. Jangan lupa untuk memberikan review untuk produk yang sudah diterima\n\n\nJazakallah khoiron\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/fadkhera-nauzan-baju-koko-pria-muslim-modern-kemko-lengan-panjang-1732018482414716801', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:34:55'),
(145, 'baju', 'Fadkhera Rizqan | Baju Koko Pria Modern Premium | Atasan Muslim Lengan Panjang', 'Rp229.120', 'Rp359.000', '-', 'Terjual 21', '5', 'Kondisi: Baru | Berat Satuan: 300 g | Min. Beli: 1 Buah | Kategori: Baju Koko Pria | Etalase: Semua Etalase', 'Warna foto mungkin tidak 100% sama dengan produk aslinya, disebabkan oleh faktor cahaya pada saat take foto, atau kondisi gadget yang digunakan\n\n\n1. Harap dipastikan bahwa pesanan sudah sesuai sebelum check out\n2. Klaim produk wajib menyertakan video unboxing\n3. Setelah barang sampai mohon untuk di cek kelengkapan dan pastikan barang yang diterima dalam kondisi baik sebelum tekan \"Pesan Diterima\"\n4. Jangan lupa untuk memberikan review untuk produk yang sudah diterima\n\n\nDemi menjaga keberkahan dan kenyamanan dalam bertransaksi, kami tidak menyarankan untuk menggunakan metode pembayaran Paylater.\nMetode pembayaran Paylater tidak dapat kami nonaktifkan karena merupakan bawaan dari sistem.\n\n\nJazakallah khoiron\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/fadkhera-rizqan-baju-koko-pria-modern-premium-atasan-muslim-lengan-panjang-1733985160638203777', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:35:04'),
(146, 'baju', 'Fadkhera X Erlan Couple Father & Son | Baju Koko Anak Lengan Panjang | Lebaran 2026', 'Rp249.000', '-', '-', 'Terjual 6', '5', 'Kondisi: Baru | Berat Satuan: 300 g | Min. Beli: 1 Buah | Kategori: Baju Koko Pria | Etalase: Semua Etalase', 'Karakter Koko ModernFadkhera X Erlan Couple Father & Son | Baju Koko Anak Lengan Panjang | Lebaran 2026\n\n\nPremium quality dengan detail tinggi\nHandfeel berbahan shining\nSoft touch\nMaterial bertekstur lembut dan tebal\nVariasi design motif yang Eksklusif & Original Design dari Fadkhera\n\nFeature\n\n\nModern spread collar\nBagian lengan yang bisa disesuaikan (Long Sleeve)\nMudah di setrika dan tidak gampang kusut\nModern size cutting (ditengah tantara reguler dan slimfit)\n\nPenukaran dan Pengembalian\n\nAnda memiliki waktu 14 hari sejak barang diterima untuk melakukan penukaran dan pengembalian barang Anda. Syarat, ketentuan dan informasi lebih lanjut silahkan kunjungi halaman klaim garansi.\n\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/fadkhera-x-erlan-couple-father-son-baju-koko-anak-lengan-panjang-lebaran-2026-1734120730429917057', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:35:13'),
(147, 'baju', 'Fadkhera Kamil Black Baju Koko Basic Pria Dewasa Kemeja Polos Lengan Panjang', 'Rp222.400', 'Rp279.000', '-', 'Terjual 11', '5', 'Kondisi: Baru | Berat Satuan: 350 g | Min. Beli: 1 Buah | Kategori: Kemeja Pria | Etalase: Sale Up To 35', 'Koko essential series elegan berwarna black yang simpel dan timeless. Warna black dalam fashion melambangkan power, elegance, dan sophistication.\nOVERVIEW\n– Koko modern berkualitas premium dengan detail tinggi\n\n– Size modern fit diantara Reguler dan Slim Fit.\n\n– Modern spread collar.\n\n– Handfeel bahan lembut dan mengkilap soft eksklusif.\n\n– Tidak mudah kusut.\n\n– Mudah disetrika.\n\n– Serat benang padat.\nPETUNJUK PERAWATAN\nMencuci dengan suhu yang rendah, tidak diberi pemutih, dan disetrika dengan suhu sedang akan membantu mempertahankan warna dan bahan.\n- Cuci dengan suhu 30°C\n\n- Jangan diberi pemutih\n\n- Dicuci kering profesional\n\n- Dikeringkan mesin pengering dengan suhu rendah\n\n- Disetrika dengan suhu sedang\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/fadkhera-kamil-black-baju-koko-basic-pria-dewasa-kemeja-polos-lengan-panjang-1730458320736192385', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:35:22'),
(148, 'baju', 'Fadkhera Khazeen Baju Koko Pria Muslim Modern Kemko Lengan Panjang', 'Rp249.000', 'Rp359.000', '-', 'Terjual 21', '5', 'Kondisi: Baru | Berat Satuan: 300 g | Min. Beli: 1 Buah | Kategori: Baju Koko Pria | Etalase: Semua Etalase', 'Karakter Koko Modern Fadkhera Official Khazeen Baju Koko Pria Muslim Modern Kemko Lengan Panjang\n\n\nPremium quality dengan detail tinggi\nHandfeel berbahan shining - soft touch\nMaterial bertekstur lembut dan tebal\nVariasi design motif yang Eksklusif & original dari Fadkhera\n\nFEATURE\n\n\nModern spread collar\nBagian lengan yang bisa disesuaikan (Long Sleeve)\nMudah di setrika dan tidak gampang kusut\nModern size cutting (ditengah tantara reguler dan slimfit)\n\nPENUKARAN & PENGEMBALIAN\n\nAnda memiliki waktu 14 hari sejak barang diterima untuk melakukan penukaran dan pengembalian barang Anda. Syarat, ketentuan dan informasi lebih lanjut silahkan kunjungi halaman klaim garansi.\n\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/fadkhera-khazeen-baju-koko-pria-muslim-modern-kemko-lengan-panjang-1732591749260609409', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:35:31'),
(149, 'baju', 'Fadkhera Alzam Baju Kaos T-Shirt Pria Dewasa', 'Rp158.000', 'Rp199.000', '-', 'Terjual 50+', '5', 'Kondisi: Baru | Berat Satuan: 250 g | Min. Beli: 1 Buah | Kategori: Kaos Pria | Etalase: Semua Etalase', 'Stretch T shirt berbahan elastis yang kuat dengan cool-feel technology yang sejuk dan dingin saat digunakan di segala aktivitas.\n\n\nOverview :\n- Strong dan durable stretch fabric dengan cool feel technology.\n- Cutting modern fit\n- Fadkhera signature T-shirt style collar\n- Bahan soft dan kuat, tidak mudah molor\n\n\nWarna : Black, Navy, Orange, Olive,Brown\n\n\nMaterial : Stretch premium fabric\n-\nWarna foto mungkin tidak 100% sama dengan produk aslinya, disebabkan oleh faktor cahaya pada saat take foto, atau kondisi gadget yang digunakan\n\n\n1. Harap dipastikan bahwa pesanan sudah sesuai sebelum check out\n2. Klaim produk wajib menyertakan video unboxing\n3. Setelah barang sampai mohon untuk di cek kelengkapan dan pastikan barang yang diterima dalam kondisi baik sebelum tekan \"Pesan Diterima\"\n4. Jangan lupa untuk memberikan review untuk produk yang sudah diterima\n\n\nJazakallah khoiron\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/t-shirt-fadkhera-alzam-kaos-muslim-modern-pria-dewasa-1729644564504873857', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:35:40'),
(150, 'baju', 'Fadkhera Ruhayli | Baju Koko Pria Modern Premium | Atasan Muslim Lengan Panjang', 'Rp247.200', '-', '-', 'Terjual 12', '5', 'Kondisi: Baru | Berat Satuan: 300 g | Min. Beli: 1 Buah | Kategori: Baju Koko Pria | Etalase: Semua Etalase', 'Warna foto mungkin tidak 100% sama dengan produk aslinya, disebabkan oleh faktor cahaya pada saat take foto, atau kondisi gadget yang digunakan\n\n\n1. Harap dipastikan bahwa pesanan sudah sesuai sebelum check out\n2. Klaim produk wajib menyertakan video unboxing\n3. Setelah barang sampai mohon untuk di cek kelengkapan dan pastikan barang yang diterima dalam kondisi baik sebelum tekan \"Pesan Diterima\"\n4. Jangan lupa untuk memberikan review untuk produk yang sudah diterima\n\n\nDemi menjaga keberkahan dan kenyamanan dalam bertransaksi, kami tidak menyarankan untuk menggunakan metode pembayaran Paylater.\nMetode pembayaran Paylater tidak dapat kami nonaktifkan karena merupakan bawaan dari sistem.\n\n\nJazakallah khoiron\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/fadkhera-ruhayli-baju-koko-pria-modern-premium-atasan-muslim-lengan-panjang-1734362566198855553', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:35:48'),
(151, 'baju', 'Buai Baby - Mahika Baju One Set Anak - Usia 6 Bulan - 3 tahun', 'Rp41.690', 'Rp90.000', '-', 'Terjual 16', '5', 'Kondisi: Baru | Berat Satuan: 250 g | Min. Beli: 1 Buah | Kategori: Pakaian Bayi Laki-laki | Etalase: Semua Etalase', '| • M A H I K A S E T • |\n\n------------\n\n100% Realpict & Original Buai Baby\n\nAvailable Colors :\n- Maroon\n- Toffe\n\nSize Chart :\n~ Size S (6-12 Bulan)\n• Lebar Dada : 28cm\n• Panjang Baju : 31cm\n• Panjang Celana : 21cm\n\n~ Size M (1-2 Tahun)\n• Lebar Dada : 30cm\n• Panjang Baju : 33cm\n• Panjang Celana : 23cm\n\n~ Size L (2-3 Tahun)\n• Lebar Dada : 32cm\n• Panjang Baju : 35cm\n• Panjang Celana : 25cm\n\n~ Size XL (4-5 Tahun)\n• Lebar Dada : 34cm\n• Panjang Baju : 37cm\n• Panjang Celana : 27cm\n\nDeskripsi Produk\n- Local Manufactured\n- Standar Nasional Indonesia ( SNI Certified)\n- Bahan : Cotton Combed 30s\n- Very Comfortable Moms\n------------\nINFO & SARAN\n- Barang yang kami kirim 100% BARU dan ORIGINAL\n- Tidak bisa dipilih = SOLD OUT ❌(Dalam Proses Produksi)\n- Produk yang masih bisa di Pilih Variasi = Ready Stok ✔️\n- Usia (bulan) hanya perkiraan/referensi, untuk menghindari kesalahan size, Mohon untuk diukur sesuai ukuran yg sudah tertera seperti Lebar Dada dan Panjang.\n- Di ukur lebih akurat\n- Untuk Jadwal Pengiriman Senin - Sabtu , Minggu dan Tanggal Merah Nasional Libur pengiriman\n- Pesanan yang masuk sebelum jam 15.00 akan dikirim di hari yang sama\n\n*Jika Ada Masalah Dengan Produk Yang Kami Kirim (Cacat / Kurang) Harap Diskusikan Terlebih Dahulu Dengan Admin.\n*Sedikit perbedaan warna juga kemungkinan terjadi karena resolusi, kecerahan, kontras dari layar komputer\n\n#romperbayi #bajubayi #bajuanak #jumperbayi #local #baju #kaosbayi #kaosanak #bajubayipolos\nLihat Lebih Sedikit', 'https://www.tokopedia.com/buai-baby-official/buai-baby-mahika-baju-one-set-anak-usia-6-bulan-3-tahun-1729515177960114784', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:35:56'),
(152, 'baju', 'Fadkhera Haifar White | Baju Koko Pria Modern Premium | Atasan Muslim Lengan Panjang', 'Rp263.200', '-', '-', 'Terjual 6', '5', 'Kondisi: Baru | Berat Satuan: 300 g | Min. Beli: 1 Buah | Kategori: Baju Koko Pria | Etalase: Semua Etalase', 'Tampil maksimal disetiap kesempatan dengan Baju Koko Pria Lengan Panjang & Pendek Terbaru 2026 Premium Kemeja Muslim Casual Haifar dari Fadkhera. Kemeja koko premium terbaru ini dirancang khusus untuk memberikan kenyamanan ekstra, baik untuk momen ibadah maupun aktivitas produktif Anda.\n\n\nSebagai opsi daily wear yang modern, baju muslim pria ini memiliki potongan kasual yang sangat fleksibel. Sempurna saat dipadukan dengan koleksi celana panjang harian kami, atau dilapisi dengan jaket saat Anda membutuhkan gaya berlapis (layering) yang rapi namun tetap santai.\n\n\nPENAWARAN SPESIAL: Dapatkan bonus eksklusif parfum sholat gratis untuk pembelian 400rb (selama persediaan masih ada).\n\n\nCharacter :\n- Premium quality dengan detail tinggi\n- Handfeel berbahan mengkilat soft touch\n- Material bertekstur lembut dan tebal\n- Variasi Design yang unik\n\n\nFeature :\n- Modern spread collar\n- Bagian lengan yang bisa disesuaikan (Long Sleeve)\n- Mudah di setrika dan tidak gampang kusut\n- Modern size cutting (antara reguler dan slimfit)\n\n\nColor :\nWhite\n\n\nMaterial :\nCotton 100%\n\n\nWarna foto mungkin tidak 100% sama dengan produk aslinya, disebabkan oleh faktor cahaya pada saat take foto, atau kondisi gadget yang digunakan\n\n\n1. Harap dipastikan bahwa pesanan sudah sesuai sebelum check out\n2. Klaim produk wajib menyertakan video unboxing\n3. Setelah barang sampai mohon untuk di cek kelengkapan dan pastikan barang yang diterima dalam kondisi baik sebelum tekan \"Pesan Diterima\"\n4. Jangan lupa untuk memberikan review untuk produk yang sudah diterima\n\n\nJazakallah khoiron\n#BajuKokoPria #KemejaKoko #BajuMuslimPria #KokoLenganPendek #KokoLenganPanjang #Fadkhera #OutfitPria #KokoPremium2026\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/fadkhera-haifar-white-baju-koko-pria-modern-premium-atasan-muslim-lengan-panjang-1734304007958464385', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:36:04'),
(153, 'baju', 'Fadkhera Aqil | Baju Koko Pria Modern Premium | Atasan Muslim Lengan Panjang', 'Rp247.200', '-', '-', 'Terjual 3', '5', 'Kondisi: Baru | Berat Satuan: 300 g | Min. Beli: 1 Buah | Kategori: Baju Koko Pria | Etalase: Semua Etalase', 'Warna foto mungkin tidak 100% sama dengan produk aslinya, disebabkan oleh faktor cahaya pada saat take foto, atau kondisi gadget yang digunakan\n\n\n1. Harap dipastikan bahwa pesanan sudah sesuai sebelum check out\n2. Klaim produk wajib menyertakan video unboxing\n3. Setelah barang sampai mohon untuk di cek kelengkapan dan pastikan barang yang diterima dalam kondisi baik sebelum tekan \"Pesan Diterima\"\n4. Jangan lupa untuk memberikan review untuk produk yang sudah diterima\n\n\nDemi menjaga keberkahan dan kenyamanan dalam bertransaksi, kami tidak menyarankan untuk menggunakan metode pembayaran Paylater.\nMetode pembayaran Paylater tidak dapat kami nonaktifkan karena merupakan bawaan dari sistem.\n\n\nJazakallah khoiron\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/fadkhera-aqil-baju-koko-pria-modern-premium-atasan-muslim-lengan-panjang-1734214570716727169', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:36:12'),
(154, 'baju', 'Baju Tidur Bayi Newborn Usia 0 - 3 Bulan | Buai Baby Lula Sleepsuit', 'Rp11.975', 'Rp95.000', '-', 'Terjual 40+', '5', 'Kondisi: Baru | Berat Satuan: 250 g | Min. Beli: 1 Buah | Kategori: Piyama Bayi | Etalase: Semua Etalase', '| • L U L A S L E E P S U I T • |\n\n\n------------\n100% Realpict & Original Buai Baby\n\n\nAvailable Colors :\n- Toffe\n- Lightbrown\n- Darkchoco\n- Army\n\n\nSize Chart:\n~ All size (0-3 Month)\n- Lebar Dada : 24cm\n- Panjang Badan : 47cm\n\n\nDeskripsi Produk\n- Local Manufactured\n- Standar Nasional Indonesia ( SNI Certified)\n- Bahan : Cotton Combed 30s\n- Rekomendasi pemakaian BB maksimal 6 kg\n- Very Comfortable Moms\n\n\n------------\n\n\nINFO & SARAN\n- Barang yang kami kirim 100% BARU dan ORIGINAL\n- Tidak bisa dipilih = SOLD OUT (Dalam Proses Produksi)\n- Produk yang masih bisa di Pilih Variasi = Ready Stok\n- Usia (bulan) hanya perkiraan/referensi, untuk menghindari kesalahan size, Mohon untuk diukur sesuai ukuran yg sudah tertera seperti Lebar Dada dan Panjang.\n- Di ukur lebih akurat\n- Untuk Jadwal Pengiriman Senin - Sabtu , Minggu dan Tanggal Merah Nasional Libur pengiriman\n- Pesanan yang masuk sebelum jam 15.00 akan dikirim di hari yang sama\n\n\n*Jika Ada Masalah Dengan Produk Yang Kami Kirim (Cacat / Kurang) Harap Diskusikan Terlebih Dahulu Dengan Admin.\n*Sedikit perbedaan warna juga kemungkinan terjadi karena resolusi, kecerahan, kontras dari layar komputer\n\n\n\n\n#romperbayi #bajubayi #bajuanak #jumperbayi #local #baju #kaosbayi #kaosanak #bajubayipolos\nLihat Lebih Sedikit', 'https://www.tokopedia.com/buai-baby-official/baju-tidur-bayi-newborn-usia-0-3-bulan-buai-baby-lula-sleepsuit-1736818822808897120-1736818835130648160', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:36:19'),
(155, 'baju', 'Fadkhera  Najib Baju Koko Pria Dewasa Lengan Panjang', 'Rp249.000', 'Rp359.000', '-', 'Terjual 3', '5', 'Kondisi: Baru | Berat Satuan: 300 g | Min. Beli: 1 Buah | Kategori: Baju Koko Pria | Etalase: Semua Etalase', 'Koko Modern Eksklusif dengan perpaduan motif Modern Geometric berwarna white - navy dibagian atas lengan yang menggambarkan fashion futuristik. Dipadukan dengan kombinasi warna Navy yang dominan, menjadikan penampilan fashion yang maksimal untuk aktifitas daily anda.\n\n\nCharacter :\n- Premium quality dengan detail tinggi\n- Handfeel berbahan mengkilat soft touch\n- Material bertekstur lembut dan tebal\n- Variasi Design yang unik\n\n\nFeature :\n- Modern spread collar\n- Bagian lengan yang bisa disesuaikan (long sleeve)\n- Mudah di setrika dan tidak gampang kusut\n- Modern size cutting (antara reguler dan slimfit)\n\n\nColor :\nGrey & White\n\n\nMaterial :\nEasy Care Soft Touch Fabrics\n\n\n\n\nStory telling:\nMonochrome Magic\nTampil maksimal tidak selalu tentang warna mencolok. Gaya monokrom, dengan paduan satu palet warna dominan, menciptakan kesan bersih dan modern yang sangat memukau. Ini adalah seni sederhana namun penuh dampak.\n\n\nMix & Match:\nCharacter Styling\nFashion adalah cara untuk menceritakannya tanpa perlu berbicara. Pendekatan di mana pakaian menjadi babak baru dari narasi dan perjalanan hidup Anda. Character produk ini tetap selalu melekat dengan Halal Lifestyle.\nDalam meramu sebuah style, tidak ada elemen yang diabaikan; semuanya dirancang untuk memadukan estetika dan fungsi. Mulai dari koko modern bermotif geometrik, Vest RAYYAN Black berstruktur yang ultra light hingga Celana MAAZ yang memberikan keseimbangan antara gaya dan kenyamanan, gaya ini adalah bentuk totalitas Fadkhera untuk Styling Anda.\n\n\nWarna foto mungkin tidak 100% sama dengan produk aslinya, disebabkan oleh faktor cahaya pada saat take foto, atau kondisi gadget yang digunakan\n\n\n1. Harap dipastikan bahwa pesanan sudah sesuai sebelum check out\n2. Klaim produk wajib menyertakan video unboxing\n3. Setelah barang sampai mohon untuk di cek kelengkapan dan pastikan barang yang diterima dalam kondisi baik sebelum tekan \"Pesan Diterima\"\n4. Jangan lupa untuk memberikan review untuk produk yang sudah diterima\n\n\nJazakallah khoiron\nLihat Lebih Sedikit', 'https://www.tokopedia.com/fadkhera-official/fadkhera-najib-baju-koko-pria-dewasa-lengan-panjang-1730835160204347265', 'data:image/svg+xml,%3csvg xmlns=%27http://www.w3.org/2000/svg%27 version=%271.1%27 width=%27100%27 h', '2026-09-28 07:36:28'),
